import AppKit
import CryptoKit
import Foundation

final class ClipboardMonitor {
    /// Images bigger than this are kept on disk instead of inline in SQLite.
    private static let maxInlineImageBytes = 4_000_000
    private static let pollInterval = 500

    /// Types password managers and other apps use to mark content that must not
    /// be recorded. Respecting them is the standard macOS convention.
    private static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type"
    ]

    private static let sensitiveBundleIdentifiers = [
        "com.agilebits.onepassword",
        "com.1password",
        "com.bitwarden",
        "com.apple.keychainaccess",
        "com.lastpass",
        "com.callpod.keeper",
        "com.dashlane",
        "org.keepassxc",
        "in.sinew.enpass",
        "com.mattbierner"
    ]

    private let persistence: PersistenceManager
    private let preferences: PreferencesStore
    private let pasteboard = NSPasteboard.general
    private let queue = DispatchQueue(label: "kop.clipboard.monitor", qos: .utility)
    private var timer: DispatchSourceTimer?
    /// Guarded by a lock, not the queue: the queue can be parked waiting on the
    /// main thread (`askUserToSave`), so the main thread must never `queue.sync`.
    private let changeCountLock = NSLock()
    private var lastChangeCount: Int
    private var paused = false

    /// Read from the menu bar; mirrored so the UI never touches queue state.
    private(set) var isPaused = false

    init(persistence: PersistenceManager, preferences: PreferencesStore) {
        self.persistence = persistence
        self.preferences = preferences
        self.lastChangeCount = pasteboard.changeCount
    }

    func start() {
        queue.async { [weak self] in
            guard let self, self.timer == nil else { return }
            let timer = DispatchSource.makeTimerSource(queue: self.queue)
            timer.schedule(
                deadline: .now() + .milliseconds(Self.pollInterval),
                repeating: .milliseconds(Self.pollInterval),
                leeway: .milliseconds(120)
            )
            timer.setEventHandler { [weak self] in
                self?.pollPasteboard()
            }
            self.timer = timer
            timer.resume()
        }
    }

    func stop() {
        queue.async {
            self.timer?.cancel()
            self.timer = nil
        }
    }

    func pause() {
        isPaused = true
        queue.async { self.paused = true }
    }

    func resume() {
        isPaused = false
        queue.async {
            self.paused = false
            self.acknowledgeCurrentPasteboardState()
        }
    }

    /// Called after Kop itself writes to the pasteboard so the change is not
    /// captured back into the history.
    func acknowledgeCurrentPasteboardState() {
        changeCountLock.lock()
        lastChangeCount = pasteboard.changeCount
        changeCountLock.unlock()
    }

    private func pollPasteboard() {
        guard !paused else { return }
        changeCountLock.lock()
        let changeCount = pasteboard.changeCount
        let isNew = changeCount != lastChangeCount
        lastChangeCount = changeCount
        changeCountLock.unlock()
        guard isNew else { return }

        guard let item = pasteboard.pasteboardItems?.first else { return }
        guard !isConcealed(item) else { return }

        let sourceApp = NSWorkspace.shared.frontmostApplication
        let settings = preferences.snapshot
        guard !shouldIgnoreSensitiveContent(from: sourceApp, behavior: settings.sensitiveCaptureBehavior) else { return }

        guard let capture = capture(item: item, sourceApp: sourceApp, settings: settings) else { return }
        guard persistence.save(capture, historyLimit: settings.historyLimit) else { return }

        DispatchQueue.main.async {
            NotificationCenter.default.post(name: .clipboardHistoryChanged, object: nil)
            settings.sound.play()
        }
    }

    private func isConcealed(_ item: NSPasteboardItem) -> Bool {
        item.types.contains { Self.concealedTypes.contains($0.rawValue) }
    }

    private func shouldIgnoreSensitiveContent(
        from app: NSRunningApplication?,
        behavior: SensitiveCaptureBehavior
    ) -> Bool {
        let bundleID = app?.bundleIdentifier?.lowercased() ?? ""
        let appName = app?.localizedName?.lowercased() ?? ""
        let isSensitive = Self.sensitiveBundleIdentifiers.contains { bundleID.hasPrefix($0) }
            || ["1password", "bitwarden", "keychain", "lastpass", "keeper", "dashlane", "keepass"].contains(where: appName.contains)
        guard isSensitive else { return false }

        switch behavior {
        case .save:
            return false
        case .ignore:
            return true
        case .ask:
            return !askUserToSave(appName: app?.localizedName)
        }
    }

    /// Runs the prompt on the main thread while the monitor queue waits. Safe
    /// because `pollPasteboard` never runs on the main thread.
    private func askUserToSave(appName: String?) -> Bool {
        let semaphore = DispatchSemaphore(value: 0)
        var shouldSave = false
        DispatchQueue.main.async {
            let alert = NSAlert()
            alert.messageText = "Salvar item sensível?"
            alert.informativeText = "Kop detectou conteúdo copiado de \(appName ?? "um app sensível")."
            alert.addButton(withTitle: "Salvar")
            alert.addButton(withTitle: "Ignorar")
            // Hand focus back afterwards so the user's next Cmd+V lands where it was.
            let previousApp = NSWorkspace.shared.frontmostApplication
            NSApp.activate(ignoringOtherApps: true)
            shouldSave = alert.runModal() == .alertFirstButtonReturn
            if let previousApp, previousApp != NSRunningApplication.current {
                previousApp.activate(options: [])
            }
            semaphore.signal()
        }
        semaphore.wait()
        return shouldSave
    }

    private func capture(
        item: NSPasteboardItem,
        sourceApp: NSRunningApplication?,
        settings: PreferencesStore.Snapshot
    ) -> ClipboardCapture? {
        let make = CaptureBuilder(
            sourceAppName: sourceApp?.localizedName,
            sourceBundleIdentifier: sourceApp?.bundleIdentifier,
            createdAt: Date()
        )

        if let fileURLString = item.string(forType: .fileURL),
           let url = URL(string: fileURLString) {
            let path = url.path
            let isImageFile = ["png", "jpg", "jpeg", "gif", "tiff", "tif", "heic", "webp", "bmp"]
                .contains(url.pathExtension.lowercased())

            if isImageFile, settings.captureImagesEnabled, let imageData = try? Data(contentsOf: url) {
                return imageCapture(data: imageData, existingPath: path, builder: make)
            }

            if settings.captureFilesEnabled {
                return make.build(
                    type: .fileURL,
                    text: url.lastPathComponent,
                    path: path,
                    fingerprint: digest("\(ClipboardItemType.fileURL.rawValue):\(path)")
                )
            }
            return nil
        }

        // Rich text wins over the PDF/TIFF previews that Office and iWork put on
        // the pasteboard alongside it — the user copied text, not a picture.
        if let rtfData = item.data(forType: .rtf) {
            let plainText = NSAttributedString(rtf: rtfData, documentAttributes: nil)?.string
            return make.build(
                type: .richText,
                text: plainText,
                rich: rtfData,
                fingerprint: digest(prefix: ClipboardItemType.richText.rawValue, data: rtfData)
            )
        }

        if let pdfData = item.data(forType: .pdf) {
            return make.build(
                type: .pdf,
                text: "Documento PDF",
                binary: pdfData,
                fingerprint: digest(prefix: ClipboardItemType.pdf.rawValue, data: pdfData)
            )
        }

        if settings.captureImagesEnabled {
            for type in [NSPasteboard.PasteboardType.png, .tiff] {
                if let data = item.data(forType: type) {
                    return imageCapture(data: data, existingPath: nil, builder: make)
                }
            }
        }

        if let htmlData = item.data(forType: .html) {
            let plainText = item.string(forType: .string)
                ?? String(data: htmlData, encoding: .utf8)?
                    .replacingOccurrences(of: "<[^>]+>", with: " ", options: .regularExpression)
            return make.build(
                type: .richText,
                text: plainText,
                rich: htmlData,
                fingerprint: digest(prefix: ClipboardItemType.richText.rawValue, data: htmlData)
            )
        }

        if let text = item.string(forType: .string),
           !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return make.build(
                type: .plainText,
                text: text,
                fingerprint: digest("\(ClipboardItemType.plainText.rawValue):\(text)")
            )
        }

        return nil
    }

    private func imageCapture(
        data: Data,
        existingPath: String?,
        builder: CaptureBuilder
    ) -> ClipboardCapture? {
        let thumbnailPath = ImageThumbnail.shared.persistThumbnail(for: data)
        let isLarge = data.count > Self.maxInlineImageBytes
        // Large images stay on disk; keep a path so copying them back still works.
        let storedPath = existingPath ?? (isLarge ? ClipboardImageBridge.storeImageFile(data) : nil)
        guard !isLarge || storedPath != nil || thumbnailPath != nil else { return nil }

        return builder.build(
            type: .image,
            text: existingPath.map { URL(fileURLWithPath: $0).lastPathComponent } ?? "Imagem",
            binary: isLarge ? nil : data,
            path: storedPath,
            thumbnail: thumbnailPath,
            fingerprint: digest(prefix: ClipboardItemType.image.rawValue, data: data)
        )
    }

    private func digest(_ string: String) -> String {
        kopDigest(Data(string.utf8))
    }

    private func digest(prefix: String, data: Data) -> String {
        kopDigest(prefix: prefix, data: data)
    }
}

/// Carries the per-poll metadata shared by every capture branch.
private struct CaptureBuilder {
    let sourceAppName: String?
    let sourceBundleIdentifier: String?
    let createdAt: Date

    func build(
        type: ClipboardItemType,
        text: String?,
        rich: Data? = nil,
        binary: Data? = nil,
        path: String? = nil,
        thumbnail: String? = nil,
        fingerprint: String
    ) -> ClipboardCapture {
        ClipboardCapture(
            type: type,
            textContent: text,
            richTextData: rich,
            binaryData: binary,
            filePath: path,
            thumbnailPath: thumbnail,
            sourceAppName: sourceAppName,
            sourceBundleIdentifier: sourceBundleIdentifier,
            fingerprint: fingerprint,
            createdAt: createdAt
        )
    }
}
